package integration

import (
	"fmt"
	"time"

	"github.com/openctemio/openctem/api/pkg/domain/shared"
)

// Signing secret of a generic webhook integration
// (docs/rfcs/RFC-122-outbound-webhooks.md). The secret is generated by the
// platform, shown once on rotation and stored only encrypted, in the
// integration's metadata under server-owned keys a caller cannot set
// (they are not in the caller metadata allowlist) and a read never returns
// in clear (the response redacts every key containing "secret").
const (
	// MetaSigningSecret holds the current secret, encrypted.
	MetaSigningSecret = "signing_secret_encrypted"
	// MetaSigningSecretPrevious holds the secret replaced by the last
	// rotation, encrypted; it still signs until MetaSigningSecretPreviousUntil.
	MetaSigningSecretPrevious = "signing_secret_previous_encrypted"
	// MetaSigningSecretPreviousUntil is the end of the overlap (RFC 3339).
	MetaSigningSecretPreviousUntil = "signing_secret_previous_until"
	// MetaSigningSecretRotatedAt is when the current secret was created (RFC 3339).
	MetaSigningSecretRotatedAt = "signing_secret_rotated_at"
)

// SigningSecretOverlap is how long the previous secret keeps signing after a
// rotation, so a receiver can switch to the new one without dropping
// deliveries.
const SigningSecretOverlap = 24 * time.Hour

// ErrSigningSecretUnreadable: a secret is stored but does not decrypt. The
// delivery fails rather than going out unsigned to a receiver that verifies.
var ErrSigningSecretUnreadable = fmt.Errorf("%w: the webhook signing secret cannot be decrypted; rotate it", shared.ErrValidation)

// SigningSecrets returns the secrets a delivery is signed with at now: the
// current one, then the previous one while its overlap lasts. None when no
// secret was ever generated (the delivery goes out unsigned).
func SigningSecrets(meta map[string]any, decrypt func(string) (string, error), now time.Time) ([]string, error) {
	cur, _ := meta[MetaSigningSecret].(string)
	if cur == "" {
		return nil, nil
	}
	plain, err := decrypt(cur)
	if err != nil || plain == "" {
		return nil, ErrSigningSecretUnreadable
	}
	out := []string{plain}
	prev, _ := meta[MetaSigningSecretPrevious].(string)
	until, _ := meta[MetaSigningSecretPreviousUntil].(string)
	if prev == "" || until == "" {
		return out, nil
	}
	end, err := time.Parse(time.RFC3339, until)
	if err != nil || !now.Before(end) {
		return out, nil
	}
	if p, err := decrypt(prev); err == nil && p != "" {
		out = append(out, p)
	}
	return out, nil
}

// SigningSecretStatus is what may be read about a signing secret: whether
// one exists and the rotation times, never the secret.
type SigningSecretStatus struct {
	Configured         bool       `json:"configured"`
	RotatedAt          *time.Time `json:"rotated_at,omitempty"`
	PreviousValidUntil *time.Time `json:"previous_valid_until,omitempty"`
}

// SigningSecretStatusOf reads the status from the metadata at now.
func SigningSecretStatusOf(meta map[string]any, now time.Time) SigningSecretStatus {
	st := SigningSecretStatus{}
	if cur, _ := meta[MetaSigningSecret].(string); cur != "" {
		st.Configured = true
	}
	if v, _ := meta[MetaSigningSecretRotatedAt].(string); v != "" {
		if t, err := time.Parse(time.RFC3339, v); err == nil {
			st.RotatedAt = &t
		}
	}
	if v, _ := meta[MetaSigningSecretPreviousUntil].(string); v != "" {
		if t, err := time.Parse(time.RFC3339, v); err == nil && now.Before(t) {
			st.PreviousValidUntil = &t
		}
	}
	return st
}
